// WORKSHOP DEMO: replace DEMO_CHANGE_ME before exposing this endpoint.
// In production, prefer Webhook Header Auth credentials or a secret manager.
const EXPECTED_SECRET = 'DEMO_CHANGE_ME';
const headers = $json.headers || {};
const supplied = headers['x-workshop-secret'] || headers['X-Workshop-Secret'];
const body = $json.body || {};

if (supplied !== EXPECTED_SECRET) {
  return { json: { accepted: false, httpStatus: 401, error: 'unauthorized', message: 'Invalid webhook secret' } };
}

const name = String(body.name || '').trim().replace(/\s+/g, ' ');
const email = String(body.email || '').trim().toLowerCase();
const company = String(body.company || '').trim();
const message = String(body.message || '').trim();
const source = String(body.source || 'website').trim();

const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
if (!name || !emailOk || !message) {
  return { json: { accepted: false, httpStatus: 400, error: 'validation_error',
    details: { name: Boolean(name), email: emailOk, message: Boolean(message) } } };
}

// Simple deterministic key for this workshop. For production use a database unique constraint.
const idempotencyKey = String(body.idempotency_key || email);
const store = $getWorkflowStaticData('global');
store.seenLeads = store.seenLeads || {};
if (store.seenLeads[idempotencyKey]) {
  return { json: { accepted: false, duplicate: true, httpStatus: 200,
    leadId: store.seenLeads[idempotencyKey], idempotencyKey,
    status: 'duplicate_ignored', message: 'This lead was already processed.' } };
}
const leadId = `lead_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
store.seenLeads[idempotencyKey] = leadId;

// PII masking before any model call. The original values stay in n8n execution data;
// configure execution-data retention/redaction appropriately in production.
const maskedMessage = message
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL]')
  .replace(/(\+?\d[\d\s().-]{7,}\d)/g, '[PHONE]');
const maskedName = '[PERSON]';
const maskedEmail = '[EMAIL]';

const disposableDomains = ['mailinator.com','10minutemail.com','guerrillamail.com','tempmail.com'];
const domain = email.split('@')[1] || '';
if (disposableDomains.includes(domain)) {
  return { json: { accepted: false, httpStatus: 422, error: 'disposable_email',
    message: 'Disposable email domains are not accepted.' } };
}

let score = 20;
if (company) score += 20;
if (message.length > 40) score += 10;
if (/\b(demo|quote|pricing|purchase|automation|budget|devis|achat)\b/i.test(message)) score += 30;
if (source === 'referral') score += 10;
score = Math.min(score, 100);

const aiPrompt = `Classify this business lead. Return ONLY valid JSON with keys classification (high_intent|medium_intent|low_intent), summary (max 35 words), recommended_action (contact|nurture|ignore). Do not infer identity. Data: company=${company || 'unknown'}; message=${maskedMessage}; deterministic_score=${score}.`;
return { json: {
  accepted: true, duplicate: false, leadId, idempotencyKey,
  lead: { name, email, company, message, source },
  masked: { name: maskedName, email: maskedEmail, message: maskedMessage },
  score, aiPrompt, piiMaskedBeforeAI: true,
  receivedAt: new Date().toISOString()
} };

// Read the normalized lead from the earlier node because HTTP Request replaces its input.
const base = $('Validate + Normalize + PII Mask + Idempotency').first().json;
let ai = null;
let aiLevel = 'rules_fallback';
let aiLatencyMs = null;
const started = Date.now();

try {
  const raw = $json.message?.content || $json.body?.message?.content || '';
  const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  const allowedClass = ['high_intent','medium_intent','low_intent'];
  const allowedAction = ['contact','nurture','ignore'];
  if (parsed && allowedClass.includes(parsed.classification) &&
      typeof parsed.summary === 'string' &&
      allowedAction.includes(parsed.recommended_action)) {
    ai = parsed;
    aiLevel = 'ollama_local';
    aiLatencyMs = Date.now() - started;
  }
} catch (e) {
  // Invalid/unavailable model output: use deterministic rules below.
}
if (!ai) {
  const classification = base.score >= 70 ? 'high_intent' : base.score >= 40 ? 'medium_intent' : 'low_intent';
  ai = {
    classification,
    summary: 'Rule-based classification used because the local model was unavailable or returned invalid JSON.',
    recommended_action: classification === 'high_intent' ? 'contact' : classification === 'medium_intent' ? 'nurture' : 'ignore'
  };
}
const audit = {
  leadId: base.leadId,
  executionId: $execution.id,
  receivedAt: base.receivedAt,
  processedAt: new Date().toISOString(),
  score: base.score,
  classification: ai.classification,
  recommendedAction: ai.recommended_action,
  aiLevel,
  aiLatencyMs,
  piiMaskedBeforeAI: true,
  validation: 'passed',
  idempotencyKey: base.idempotencyKey
};
return { json: {
  status: 'processed',
  leadId: base.leadId,
  lead: base.lead,
  score: base.score,
  ai,
  aiLevel,
  piiMaskedBeforeAI: true,
  audit,
  nextStep: ai.recommended_action === 'contact' ? 'human_review_then_contact' : ai.recommended_action
} };
